with mapa (questao_id, unidade_pedagogica_id, ordem_unidade, tema, justificativa, confianca) as (
  values
    (240, 'd54fb675-78a8-4efb-a99a-44359555d28f'::uuid, 1, 'Pretérito imperfeito do subjuntivo — desinência -sse (origem=AUTORAL_PAPIRO)', 'ORIGEM: AUTORAL_PAPIRO (banca=''Papiro'', concurso=''PAPIRO - Estilo Fundatec - BM RS'', 2026) — material suplementar de prática, NÃO conta como incidência histórica real da Fundatec no raio-x pré-edital. Regra testada: em ''Se eu estudasse mais, teria melhor desempenho'', ''estudasse'' está no pretérito imperfeito do subjuntivo, reconhecido pela desinência ''-sse-''. Categoria: A) regra produtiva.', 'alta'),
    (241, 'd54fb675-78a8-4efb-a99a-44359555d28f'::uuid, 1, 'Futuro do subjuntivo × infinitivo pessoal (origem=AUTORAL_PAPIRO)', 'ORIGEM: AUTORAL_PAPIRO — material suplementar de prática, NÃO conta como incidência histórica real. Regra testada: em ''Quando eu chegar, avisarei'', ''chegar'' está no futuro do subjuntivo. CORREÇÃO APLICADA: a distinção com o infinitivo pessoal (formas coincidentes em verbos regulares) deve ser ensinada como teste contextual — ''quando''/''se'' com valor de eventualidade futura é pista forte de futuro do subjuntivo, preposição introduzindo oração reduzida é pista de infinitivo — dependendo da estrutura sintática e da função da oração, nunca como regra universal infalível. Categoria: D) contraste.', 'alta'),
    (242, 'd54fb675-78a8-4efb-a99a-44359555d28f'::uuid, 1, 'Futuro do pretérito do indicativo — desinência -ria (origem=AUTORAL_PAPIRO)', 'ORIGEM: AUTORAL_PAPIRO — material suplementar de prática, NÃO conta como incidência histórica real. Regra testada: ''faria'' está no futuro do pretérito do indicativo, reconhecido pela desinência ''-ria-''. Categoria: A) regra produtiva.', 'alta'),
    (692, 'd54fb675-78a8-4efb-a99a-44359555d28f'::uuid, 1, 'Correlação condicional: se+pretérito imperfeito do subjuntivo ↔ futuro do pretérito do indicativo', 'Questão real (Fundatec, Esc Pol PC-RS/2026). Regra testada: ''justificaria'' está no futuro do pretérito do indicativo, em correlação condicional com ''se isso viesse'' (pretérito imperfeito do subjuntivo), expressando ação hipotética. NÚCLEO IMPORTANTE confirmado por prova real recente — ensinar forma → relação temporal → valor hipotético/condicional, não apenas a desinência mecanicamente. Categoria: A) regra produtiva.', 'alta'),
    (763, 'd54fb675-78a8-4efb-a99a-44359555d28f'::uuid, 1, 'Futuro do presente do indicativo — reescrita a partir de forma composta', 'Questão real (Fundatec, Tec Per IGP RS/Técnico em Química/2025). Regra testada: ''têm'' (3ª pl.), reescrito no futuro do presente do indicativo, torna-se ''terão''. CORREÇÃO APLICADA: a fórmula ''infinitivo + -ão'' é regra de bolso válida para verbos regulares, mas tem limite explícito em verbos com radical futuro irregular (fazer→farão, dizer→dirão, trazer→trarão) — ensinar regra de bolso + limite da regra de bolso. Categoria: A) regra produtiva.', 'alta'),
    (764, 'd54fb675-78a8-4efb-a99a-44359555d28f'::uuid, 1, 'Valores semânticos dos modos verbais em texto real (indicativo × subjuntivo)', 'Questão real (Fundatec, Del Pol PC-RS/2025). Regra testada: ''saibam'' (presente do subjuntivo) exprime conjectura incerta mas possível, em contraste com formas do indicativo do mesmo texto. CORREÇÃO APLICADA: não ensinar como definição absoluta (''indicativo=certeza, subjuntivo=incerteza, imperativo=ordem'') — apresentar como primeiro mapa mental útil, mas com nuance: indicativo tende a apresentar o conteúdo como fato/ocorrência/constatação assumida pelo enunciador; subjuntivo aparece frequentemente em hipótese/possibilidade/desejo/dúvida/condição/eventualidade/avaliação/não asserção; imperativo pode expressar ordem/pedido/conselho/convite/orientação/instrução — a questão real determina qual valor está sendo explorado no contexto. Categoria: E) habilidade semântica/interpretativa.', 'alta'),
    (765, 'd54fb675-78a8-4efb-a99a-44359555d28f'::uuid, 1, 'Pretérito perfeito do indicativo — verbo regular (perceber) × irregular (estar)', 'Questão real (Fundatec, Del Pol PC-RS/2025). Regra testada: ''percebem'' e ''estão'', reescritos no pretérito perfeito do indicativo (3ª pl.), tornam-se ''perceberam'' (regular) e ''estiveram'' (irregular). Categoria: A) regra produtiva + B) regra morfológica (irregularidade verbal).', 'alta'),
    (766, 'd54fb675-78a8-4efb-a99a-44359555d28f'::uuid, 1, 'Futuro do presente do indicativo do verbo ''vir'' + concordância nominal do particípio', 'Questão real (Fundatec, Del Pol PC-RS/2025). Regra testada: ''o controle vem'' reescrito no plural e no futuro do presente torna-se ''os controles virão disfarçados'' (vir, 3ª pl. futuro do presente, com concordância do particípio adjetivado). Distratores exploram a confusão clássica VIR × VER na 3ª pessoa do plural (veem/vieram/viram/vêm × virão). Categoria: A) regra produtiva + D) contraste.', 'alta'),
    (767, 'd54fb675-78a8-4efb-a99a-44359555d28f'::uuid, 1, 'Futuro do pretérito do indicativo × inexistência de ''futuro do pretérito do subjuntivo''', 'Questão real (Fundatec, GCM Sant''Ana do Livramento/2025). Regra testada: ''fracassaria'' está no modo indicativo, futuro do pretérito. CONFIRMADO: o modo subjuntivo possui apenas os tempos simples presente, pretérito imperfeito e futuro — ''futuro do pretérito do subjuntivo'' NÃO EXISTE, sendo pegadinha típica de banca (nomes plausíveis de tempos inexistentes). Categoria: D) contraste.', 'alta'),
    (811, 'd54fb675-78a8-4efb-a99a-44359555d28f'::uuid, 1, 'Futuro do presente do indicativo — reescrita a partir do pretérito imperfeito', 'Questão real (Fundatec, GM Pref Imbé/2023). Regra testada: ''castigavam'' (pretérito imperfeito), reescrito no futuro do presente do indicativo (3ª pl.), torna-se ''castigarão''. Mesma regra de bolso e limite de Q763 (verbos regulares × radicais futuros irregulares). Categoria: A) regra produtiva.', 'alta'),
    (894, 'd54fb675-78a8-4efb-a99a-44359555d28f'::uuid, 1, 'Presente do subjuntivo → pretérito imperfeito do subjuntivo (mesma flexão modal)', 'Questão real (Fundatec, TA Pol Pen PP-RS/2022). Regra testada: ''estejamos'' está no presente do subjuntivo; flexionado no pretérito imperfeito do mesmo modo, torna-se ''estivéssemos''. Reaproveita o artigo ''RS Seguro'' já usado em Ortografia/Acentuação/Fonemas (conteúdos 20/26/34, já concluídos), aqui testando um par de tempos do subjuntivo. Categoria: A) regra produtiva.', 'alta')
)
select * from mapa order by questao_id, ordem_unidade;

